import { z as z7 } from "zod";
var text5 = z7.string().trim().min(1);
var texts = z7.array(text5);
var id = z7.string().regex(/^(operation|assembly|recipe|shape):[A-Za-z][A-Za-z0-9-]*$/);
var common = {
  version: z7.literal("kiln.catalog-entry.v1"),
  id,
  name: text5,
  summary: text5.max(500),
  family: text5.max(80),
  tags: texts,
  aliases: texts,
  intents: texts,
  stability: z7.enum(["stable", "experimental", "deprecated"]),
  related: z7.array(z7.object({
    id,
    relation: z7.enum(["alternative", "prerequisite", "companion"])
  }).strict()),
  references: texts,
  limitations: texts
};
var operationContractSchema = z7.object({
  signature: text5,
  returns: text5,
  units: text5,
  axes: text5,
  origin: text5,
  execution: z7.enum(["sync", "async"]),
  ownership: text5,
  coordinates: text5,
  parameters: texts,
  topology: texts,
  preservation: texts,
  semantics: texts,
  cost: text5,
  example: text5
}).strict();
var discoveryEntrySchema = z7.discriminatedUnion("kind", [
  z7.object({ ...common, kind: z7.literal("operation"), contract: operationContractSchema }).strict(),
  z7.object({ ...common, kind: z7.literal("assembly"), contract: operationContractSchema }).strict(),
  z7.object({
    ...common,
    kind: z7.literal("recipe"),
    recipe: z7.object({
      prerequisites: z7.array(id),
      steps: texts.min(1),
      example: text5,
      adaptations: texts,
      checks: texts
    }).strict()
  }).strict(),
  z7.object({
    ...common,
    kind: z7.literal("shape"),
    shape: z7.object({ tool: text5, field: text5, schema: z7.record(z7.string(), z7.unknown()) }).strict()
  }).strict()
]).superRefine((entry, ctx) => {
  if (!entry.id.startsWith(`${entry.kind}:`)) {
    ctx.addIssue({
      code: "custom",
      path: ["id"],
      message: "Entry ID namespace must match kind."
    });
  }
  if (entry.kind !== "recipe" && entry.id !== `${entry.kind}:${entry.name}`) {
    ctx.addIssue({
      code: "custom",
      path: ["id"],
      message: "Executable entry ID must contain its exact sandbox name."
    });
  }
});
function parseCatalog(value) {
  const entries = z7.array(discoveryEntrySchema).parse(value);
  const ids = new Set;
  const names = new Set;
  for (const entry of entries) {
    if (ids.has(entry.id))
      throw new Error(`Duplicate Discovery ID: ${entry.id}`);
    ids.add(entry.id);
    if (entry.kind !== "recipe") {
      if (names.has(entry.name))
        throw new Error(`Duplicate executable Discovery name: ${entry.name}`);
      names.add(entry.name);
    }
  }
  for (const entry of entries) {
    const refs = [
      ...entry.related.map((related) => related.id),
      ...entry.kind === "recipe" ? entry.recipe.prerequisites : []
    ];
    for (const ref of refs) {
      if (!ids.has(ref))
        throw new Error(`Unknown Discovery reference ${ref} in ${entry.id}`);
    }
  }
  return entries;
}

