function discoveryTokens(value) {
  return value.normalize("NFKC").replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2").replace(/([a-z0-9])([A-Z])/g, "$1 $2").toLowerCase().split(/[^\p{L}\p{N}]+/u).filter((token) => token.length > 0 && !stopwords.has(token)).map((token) => inflections[token] ?? token);
}

