// src/agent/tools.ts
init_requirements_context();
function withVisualObservation(json, visualObservation) {
  if (json && typeof json === "object" && !Array.isArray(json)) {
    return { ...json, visualObservation };
  }
  return { result: json, visualObservation };
}
async function observedMediaResult(def, pngs, json, context) {
  try {
    const value = await context.renderObservationPort({
      toolName: def.name,
      pngs,
      json,
      ...context.intent ? { intent: context.intent } : {},
      requirements: resolveRequirementsContext(context.requirements),
      ...context.generationCallBudget ? { generationCallBudget: context.generationCallBudget } : {}
    });
    return [
      new JsonBlock({
        json: withVisualObservation(json, { ok: true, value })
      })
    ];
  } catch {
    return [
      new JsonBlock({
        json: withVisualObservation(json, {
          ok: false,
          reason: "observer-unavailable"
        })
      })
    ];
  }
}
async function toCallbackResult(def, output, context = {}) {
  const multi = def.mediaMulti?.(output);
  if (multi) {
    if (context.renderObservationPort) {
      return observedMediaResult(def, multi.pngs, multi.json, context);
    }
    return [
      ...multi.pngs.map((png) => new ImageBlock({ format: "png", source: { bytes: png } })),
      new JsonBlock({ json: multi.json })
    ];
  }
  const media = def.media?.(output);
  if (media) {
    if (context.renderObservationPort) {
      return observedMediaResult(def, [media.png], media.json, context);
    }
    return [
      new ImageBlock({ format: "png", source: { bytes: media.png } }),
      new JsonBlock({ json: media.json })
    ];
  }
  const text = def.text?.(output);
  if (text !== undefined)
    return [new TextBlock(text)];
  return output;
}
function toStrandsTool(def, context = {}) {
  return tool({
    name: def.name,
    description: def.description,
    inputSchema: def.inputSchema,
    callback: async (input) => toCallbackResult(def, await def.run(input), context)
  });
}
function makeKilnNativeTools(completion, context) {
  return createKilnNativeToolRegistry(context, completion).map((def) => toStrandsTool(def, context));
}

// src/agent/hooks.ts
import {
  BeforeToolCallEvent,
  BeforeModelCallEvent,
  AfterModelCallEvent
} from "@strands-agents/sdk";
var USAGE_FIELDS = [
  "inputTokens",
  "outputTokens",
  "cacheReadInputTokens",
  "cacheWriteInputTokens"
];

class MetricsCollector {
  onEvent;
  maxSteps;
  generationCallBudget;
  modelCallRole;
  modelCallAdmission;
  toolCalls = [];
  steps = 0;
  usage;
  capped = false;
  cappedReason;
  cleanups = [];
  constructor(onEvent, maxSteps, generationCallBudget, modelCallRole = "author", modelCallAdmission) {
    this.onEvent = onEvent;
    this.maxSteps = maxSteps;
    this.generationCallBudget = generationCallBudget;
    this.modelCallRole = modelCallRole;
    this.modelCallAdmission = modelCallAdmission;
  }
  emit(event) {
    if (!this.onEvent)
      return;
    try {
      this.onEvent(event);
    } catch {}
  }
  attach(agent) {
    const offTool = agent.addHook(BeforeToolCallEvent, (event) => {
      this.toolCalls.push(event.toolUse.name);
      this.emit({ type: "tool", tool: event.toolUse.name, step: this.steps });
    });
    const offModel = agent.addHook(AfterModelCallEvent, () => {
      this.emit({ type: "model_call", step: this.steps });
    });
    const offDispatch = agent.addHook(BeforeModelCallEvent, (event) => {
      if (this.maxSteps && this.maxSteps > 0 && this.steps >= this.maxSteps) {
        this.capped = true;
        this.cappedReason = `kiln: agent step cap reached (${this.maxSteps} model calls) — aborted to bound cost`;
        event.cancel = this.cappedReason;
        return;
      }
      if (this.modelCallAdmission) {
        const decision = this.modelCallAdmission.tryAdmit({
          role: this.modelCallRole,
          ...typeof event.projectedInputTokens === "number" ? { projectedInputTokens: event.projectedInputTokens } : {}
        });
        if (!decision.ok) {
          this.capped = true;
          this.cappedReason = decision.reason;
          event.cancel = decision.reason;
          return;
        }
      }
      if (this.generationCallBudget && !this.generationCallBudget.tryConsume(this.modelCallRole)) {
        this.capped = true;
        const receipt = this.generationCallBudget.receipt();
        this.cappedReason = `kiln: generation model-call budget reached (${receipt.limit} aggregate calls) — ` + "aborted before provider dispatch to bound cost";
        event.cancel = this.cappedReason;
        return;
      }
      this.steps += 1;
    });
    this.cleanups.push(offTool, offModel, offDispatch);
    return () => this.detach();
  }
  wasCapped() {
    return this.capped;
  }
  capReason() {
    return this.cappedReason;
  }
  detach() {
    for (const off of this.cleanups) {
      try {
        off();
      } catch {}
    }
    this.cleanups = [];
  }
  recordResultUsage(usage) {
    if (!usage)
      return;
    const next = { ...this.usage };
    let recorded = false;
    for (const field of USAGE_FIELDS) {
      const value = usage[field];
      if (typeof value === "number") {
        next[field] = (next[field] ?? 0) + value;
        recorded = true;
      }
    }
    if (recorded)
      this.usage = next;
  }
  readMetrics() {
    return {
      toolCalls: [...this.toolCalls],
      steps: this.steps,
      ...this.usage ? { usage: { ...this.usage } } : {}
    };
  }
}

// src/agent/call-budget.ts
var DEFAULT_GENERATION_MODEL_CALL_LIMIT = 0;
function resolveGenerationModelCallLimit(raw) {
  if (raw === undefined || raw === null || raw === "")
    return DEFAULT_GENERATION_MODEL_CALL_LIMIT;
  const parsed = typeof raw === "number" ? raw : typeof raw === "string" && raw.trim() ? Number(raw) : NaN;
  if (!Number.isSafeInteger(parsed) || parsed < 0)
    throw new Error("Generation model-call limit must be a nonnegative safe integer; use 0 for unlimited.");
  return parsed;
}
function generationModelCallLimitFromEnv(env = process.env) {
  return resolveGenerationModelCallLimit(env.KILN_GENERATION_MAX_CALLS ?? env.KILN_AGENT_MAX_STEPS);
}
function createGenerationCallBudget(limit = DEFAULT_GENERATION_MODEL_CALL_LIMIT) {
  const resolvedLimit = resolveGenerationModelCallLimit(limit);
  let consumed = 0;
  let denied = 0;
  const byRole = {};
  return {
    tryConsume(role) {
      if (resolvedLimit > 0 && consumed >= resolvedLimit) {
        denied += 1;
        return false;
      }
      consumed += 1;
      byRole[role] = (byRole[role] ?? 0) + 1;
      return true;
    },
    receipt() {
      const remaining = resolvedLimit === 0 ? null : Math.max(0, resolvedLimit - consumed);
      return {
        limit: resolvedLimit,
        consumed,
        remaining,
        exhausted: resolvedLimit > 0 && remaining === 0,
        denied,
        byRole: { ...byRole }
      };
    }
  };
}

// src/agent/compaction.ts
import {
  AfterToolCallEvent,
  BeforeModelCallEvent as BeforeModelCallEvent2,
  TextBlock as TextBlock2
} from "@strands-agents/sdk";
var STALE_RENDER_PLACEHOLDER = "[earlier render image omitted — superseded by a newer render]";
function isImageBlock(block) {
  return block.type === "imageBlock";
}
function isToolResultBlock(block) {
  const b = block;
  return b.type === "toolResultBlock" && Array.isArray(b.content);
}
function pruneStaleRenderImages(messages, opts = {}) {
  const keep = opts.keep ?? 1;
  const bearing = [];
  for (const message of messages) {
    for (const block of message.content) {
      if (isToolResultBlock(block) && block.content.some(isImageBlock)) {
        bearing.push(block);
      }
    }
  }
  const cut = Math.max(0, bearing.length - Math.max(0, keep));
  let prunedImages = 0;
  let prunedResults = 0;
  for (const result of bearing.slice(0, cut)) {
    const images = result.content.filter(isImageBlock).length;
    const placeholder = images > 1 ? new TextBlock2(`[${images} earlier render images omitted — superseded by a newer render]`) : new TextBlock2(STALE_RENDER_PLACEHOLDER);
    const next = [];
    let placed = false;
    for (const item of result.content) {
      if (isImageBlock(item)) {
        if (!placed) {
          next.push(placeholder);
          placed = true;
        }
        continue;
      }
      next.push(item);
    }
    result.content.splice(0, result.content.length, ...next);
    prunedImages += images;
    prunedResults += 1;
  }
  return { prunedImages, prunedResults };
}
function installRenderImageCompaction(agent, opts = {}) {
  return agent.addHook(BeforeModelCallEvent2, (event) => {
    const result = pruneStaleRenderImages(event.agent.messages, opts.keep != null ? { keep: opts.keep } : {});
    if (result.prunedImages > 0 && opts.onPrune) {
      try {
        opts.onPrune(result);
      } catch {}
    }
  });
}
function installGenerationCounters(agent) {
  const counters = { modelCalls: [], renders: 0 };
  const offModel = agent.addHook(BeforeModelCallEvent2, (event) => {
    counters.modelCalls.push({
      ...typeof event.projectedInputTokens === "number" ? { inputTokens: event.projectedInputTokens } : {},
      messages: event.agent.messages.length
    });
  });
  const offTool = agent.addHook(AfterToolCallEvent, (event) => {
    const content = event.result?.content;
    if (Array.isArray(content) && content.some(isImageBlock))
      counters.renders += 1;
  });
  return {
    counters,
    uninstall: () => {
      offModel();
      offTool();
    }
  };
}

// src/agent/concurrency.ts
import { BeforeToolsEvent } from "@strands-agents/sdk";
function toolNamesInBatch(message) {
  const names = [];
  for (const block of message.content) {
    const b = block;
    if (b.type === "toolUseBlock" && typeof b.name === "string")
      names.push(b.name);
  }
  return names;
}
function rejectMixedCompletionBatch(names) {
  if (names.includes("kiln_finish") && names.length > 1)
    return "kiln_finish must run alone. No tools in this batch executed. Render or edit first, then finish in a separate call.";
  return;
}
function installCompletionBatchGuard(agent) {
  return agent.addHook(BeforeToolsEvent, (event) => {
    const rejection = rejectMixedCompletionBatch(toolNamesInBatch(event.message));
    if (rejection)
      event.cancel = rejection;
  });
}

// src/agent/providers.ts
import { CachePointBlock, TextBlock as TextBlock3 } from "@strands-agents/sdk";
var promptCacheSupport = new WeakMap;
var OPENROUTER_EFFORTS = new Set(["xhigh", "high", "medium", "low", "minimal", "none"]);
async function modelConsumesSystemPromptCachePoints(model) {
  if (!model || typeof model !== "object" || !("stream" in model))
    return false;
  const known = promptCacheSupport.get(model);
  if (known !== undefined)
    return known;
  const [anthropic, bedrock] = await Promise.allSettled([
    import("@strands-agents/sdk/models/anthropic"),
    import("@strands-agents/sdk/models/bedrock")
  ]);
  for (const result of [anthropic, bedrock]) {
    if (result.status === "rejected" && !["ERR_MODULE_NOT_FOUND", "MODULE_NOT_FOUND"].includes(result.reason?.code))
      throw result.reason;
  }
  const supported = anthropic.status === "fulfilled" && model instanceof anthropic.value.AnthropicModel || bedrock.status === "fulfilled" && model instanceof bedrock.value.BedrockModel;
  promptCacheSupport.set(model, supported);
  return supported;
}
async function toCachedSystemPrompt(text, model) {
  if (!await modelConsumesSystemPromptCachePoints(model))
    return text;
  return [new TextBlock3(text), new CachePointBlock({ cacheType: "default" })];
}

